Console.WriteLine(Rechner.Flaeche(4));        // Quadrat: 16
Console.WriteLine(Rechner.Flaeche(4, 5));     // Rechteck: 20
Console.WriteLine(Rechner.Flaeche(2, 3, 4));  // Quader-Oberfläche: 52

class Rechner
{
    public static int Flaeche(int seite)
    {
        return seite * seite;
    }

    public static int Flaeche(int laenge, int breite)
    {
        return laenge * breite;
    }

    public static int Flaeche(int a, int b, int c)
    {
        return 2 * (a * b + a * c + b * c);
    }
}

Ausgabe.Zeige(7);
Ausgabe.Zeige("sieben");
Ausgabe.Zeige(new int[] { 1, 2, 3 });

class Ausgabe
{
    public static void Zeige(int zahl)
    {
        Console.WriteLine($"Zahl: {zahl}");
    }

    public static void Zeige(string text)
    {
        Console.WriteLine($"Text: {text}");
    }

    public static void Zeige(int[] werte)
    {
        Console.WriteLine($"Array: {string.Join(", ", werte)}");
    }

    // NICHT erlaubt – unterscheidet sich nur im Rückgabetyp:
    // public static string Zeige(int zahl) { ... }
}
// Ausgabe:
// Zahl: 7
// Text: sieben
// Array: 1, 2, 3

Gruss("Mia");
Gruss("Tom", "Hallo");
Gruss("Ida", "Grüß Gott", 3);

void Gruss(string name, string wort = "Servus", int mal = 1)
{
    for (int i = 0; i < mal; i++)
    {
        Console.WriteLine($"{wort}, {name}!");
    }
}
// Ausgabe:
// Servus, Mia!
// Hallo, Tom!
// Grüß Gott, Ida!
// Grüß Gott, Ida!
// Grüß Gott, Ida!

